 "content": "def transform(grid):
    # Summarize horizontal segments by color, in color order: 3s then 2s.
    counts = {3: 0, 2: 0}
    for row in grid:
        for c, value in enumerate(row):
            if value in counts and (c == 0 or row[c - 1] != value):
                counts[value] += 1
    flat = [3] * counts[3] + [2] * counts[2]
    flat = (flat + [0] * 6)[:6]
    return [flat[:3], flat[3:]]
